// The CRM posts { event, occurred_at, data }.
// Build a human-readable alert and carry the useful bits forward.

const body = $json.body ?? $json;
const lead = body.data ?? {};
const event = body.event ?? 'unknown';

const inr = (n) => '\u20B9' + Number(n || 0).toLocaleString('en-IN');

const headline = {
  'lead.created': '\uD83D\uDFE2 New lead',
  'lead.status_changed': '\uD83D\uDD04 Status changed',
  'lead.assigned': '\uD83D\uDC64 Lead assigned',
}[event] ?? event;

const lines = [
  `${headline}: ${lead.company_name ?? 'Unknown company'}`,
  lead.contact_name ? `Contact: ${lead.contact_name}` : '',
  lead.phone ? `Phone: ${lead.phone}` : '',
  lead.email ? `Email: ${lead.email}` : '',
  lead.value ? `Value: ${inr(lead.value)}` : '',
  lead.lead_source ? `Source: ${lead.lead_source}` : '',
  event === 'lead.status_changed' && lead.previous_status
    ? `Status: ${lead.previous_status} \u2192 ${lead.status}`
    : (lead.status ? `Status: ${lead.status}` : ''),
].filter(Boolean);

return {
  json: {
    event,
    message: lines.join('\n'),
    company_name: lead.company_name ?? '',
    value: Number(lead.value || 0),
    priority: lead.priority ?? 'medium',
    lead_id: lead.id ?? '',
  },
};
